package org.schoolkernel.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.schoolkernel.contract.*;
import org.schoolkernel.application.AudienceBaseline;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.*;

/** Real published generation/repair and independent review; no operator state. */
class AudienceSolveCliIT {
    @TempDir Path temporary;
    final AudienceReviewCliIT fixtures=new AudienceReviewCliIT();
    static final Path OUTPUT=Path.of("../output/kernel/student-groups-and-coordinated-lessons/UC-9/"+System.currentTimeMillis());
    static final AtomicInteger SEQUENCE=new AtomicInteger();static final List<String> STEPS=new ArrayList<>();
    @BeforeAll static void setup()throws Exception{Files.createDirectories(OUTPUT);Files.writeString(OUTPUT.resolve("ledger.md"),"# UC-9 published generation and repair journey\n\n"+Instant.now()+"; isolated complete source/Current pairs, private pinned packaged JAR per call; base 3cb66f3. Every call checks all input bytes unchanged. No UI applies to this kernel-caller goal.\n\n");}
    @AfterAll static void finish()throws Exception{Files.writeString(OUTPUT.resolve("ledger.md"),String.join("\n\n",STEPS)+"\n\nDisposable files only; no operator baseline or browser data changed. All child processes reaped.\n",StandardOpenOption.APPEND);}
    interface Checked {void run()throws Exception;}
    void journey(String text,Checked action)throws Exception{try{action.run();STEPS.add("- PASS: "+text);}catch(Throwable error){STEPS.add("- FAIL: "+text+": "+error);throw error;}}
    JsonNode call(String command,ObjectNode definition,JsonNode candidate,ObjectNode oldDefinition,JsonNode current,int expected,String tag,String... controls)throws Exception{
        var dir=OUTPUT.resolve(String.format("%03d-%s",SEQUENCE.incrementAndGet(),tag));Files.createDirectories(dir);var jar=temporary.resolve("kernel-"+SEQUENCE.get()+".jar");Files.copy(Path.of("target/school-kernel.jar"),jar);
        var args=new ArrayList<>(List.of(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-jar",jar.toString(),command));var inputs=new LinkedHashMap<Path,byte[]>();
        input(args,inputs,dir,"--definition","definition.json",definition);
        if(candidate!=null)input(args,inputs,dir,command.equals("verify")?"--result":"--assignments","candidate.json",candidate);
        if(current!=null){input(args,inputs,dir,"--current-definition","current-definition.json",oldDefinition);input(args,inputs,dir,"--current","current.json",current);}
        args.addAll(List.of(controls));var output=dir.resolve("output.json");args.addAll(List.of("--output",output.toAbsolutePath().toString()));var log=dir.resolve("process.log");
        var process=new ProcessBuilder(args).redirectErrorStream(true).redirectOutput(log.toFile()).start();assertTrue(process.waitFor(35,TimeUnit.SECONDS));assertEquals(expected,process.exitValue(),Files.readString(log));for(var entry:inputs.entrySet())assertArrayEquals(entry.getValue(),Files.readAllBytes(entry.getKey()));var result=JsonSupport.mapper().readTree(output);
        if(result.path("schemaVersion").asInt()==2)assertTrue(new AudienceResultSchemaValidator().validate(result).isEmpty(),result.toString());
        STEPS.add("  - "+command+" "+tag+": exit "+expected+", exact input preservation; [output]("+dir.getFileName()+"/output.json), complete source/Current/candidate JSON in same directory.");return result;
    }
    static void input(List<String> args,Map<Path,byte[]> inputs,Path dir,String option,String name,JsonNode value)throws Exception{var path=dir.resolve(name);var bytes=JsonSupport.mapper().writeValueAsBytes(value);Files.write(path,bytes);inputs.put(path,bytes);args.addAll(List.of(option,path.toAbsolutePath().toString()));}
    JsonNode plan(ObjectNode d,int steps,String tag)throws Exception{return call("plan",d,null,null,null,0,tag,"--step-limit",""+steps,"--seed","0");}
    JsonNode review(ObjectNode d,JsonNode assignments,String tag)throws Exception{var r=call("review",d,assignments,null,null,0,tag);assertTrue(r.path("valid").asBoolean(),r.toString());return r.path("result");}
    JsonNode repair(ObjectNode old,JsonNode baseline,ObjectNode d,int steps,String tag)throws Exception{d.put("basedOnRevision",baseline.path("inputRevision").asString());return call("replan",d,null,old,baseline,0,tag,"--step-limit",""+steps,"--seed","0");}
    static void score(JsonNode result,long teacher,long period,long room){assertEquals(teacher,result.path("score").path("teacherAllocationChanges").asLong(),result.toString());assertEquals(period,result.path("score").path("periodMoves").asLong(),result.toString());assertEquals(room,result.path("score").path("roomOnlyMoves").asLong(),result.toString());}
    static ObjectNode row(JsonNode result,String id){return AudienceReviewCliIT.row((ArrayNode)result.path("timetable").path("assignments"),id);}
    @Test void automaticCrossDayFullAndBoundedSearch()throws Exception{journey("Default automatic parallel placement finds complete cross-day six-session timetable with actual 14/7/7 resources and no manual pairing; deterministic steps/seed repeat exact values, bounded valid candidate is independently reverified and forged collision refused",()->{
        var d=fixtures.definition();var result=plan(d,10000,"automatic-cross-day");assertEquals("FEASIBLE",result.path("status").asString());assertEquals(6,result.path("timetable").path("assignments").size());assertEquals(0,result.path("score").path("internalGapStudentPeriods").asLong());assertEquals(0,result.path("quality").path("coverageStudentPeriods").asLong());assertTrue(result.path("quality").path("teacherWorkload").get(0).path("exceedsReference").asBoolean());
        var repeat=plan(d,10000,"same-seed-exact-values");for(String field:List.of("timetable","weeklyTeacherAllocations","score","quality","searchOutcome"))assertTrue(AudiencePairValidator.equivalent(result.path(field),repeat.path(field)),field);
        var limited=plan(d,100,"bounded-valid-candidate");assertEquals("STEP_LIMIT",limited.path("terminationReason").asString());assertEquals(100,limited.path("searchOutcome").path("visitedNodes").asLong());assertFalse(limited.path("searchOutcome").path("globalOptimalityClaimed").asBoolean());assertEquals("VERIFIED",call("verify",d,limited,null,null,0,"independent-bounded-pair").path("status").asString());
        var preserved=review(d,limited,"review-retains-source-search");for(String field:List.of("seed","limit","terminationReason","searchOutcome"))assertTrue(AudiencePairValidator.equivalent(limited.path(field),preserved.path(field)),field);
        var a=(ArrayNode)result.path("timetable").path("assignments").deepCopy();AudienceReviewCliIT.row(a,"e2").put("periodId",row(result,"e1").path("periodId").asString());var invalid=call("review",d,a,null,null,0,"independent-hard-invalid");assertFalse(invalid.path("valid").asBoolean());assertFalse(invalid.has("result"));
    });}
    @Test void optionalControlsMixedAndIntentionalSharing()throws Exception{journey("All seven optional hard controls narrow automatic generation without weakening counts; mixed demand remains four actual sessions, weekly automatic continuity and explicit fixed teacher sharing survive independent review",()->{
        var d=fixtures.definition();AudienceReviewCliIT.rule(d,"start","START_TOGETHER",1,"portion-E1","portion-H3","portion-H4");AudienceReviewCliIT.rule(d,"same","SAME_DAY",1,"portion-E1","portion-H3");AudienceReviewCliIT.rule(d,"different","DIFFERENT_DAYS",1,"portion-E1","portion-E2");var allowed=AudienceReviewCliIT.rule(d,"allowed","ALLOWED",1,"portion-E1");allowed.putArray("days").add("TUESDAY");allowed.putArray("periodIds").add("tue-p2");AudienceReviewCliIT.rule(d,"fixed","FIXED",1,"portion-H1").put("periodId","thu-p4").put("day","THURSDAY");AudienceReviewCliIT.rule(d,"coverage","COVERAGE",1,"portion-E1","portion-H3","portion-H4");AudienceReviewCliIT.rule(d,"gap-free","GAP_FREE",0);
        var result=plan(d,10000,"every-hard-control");assertEquals(7,result.path("coordinationMatches").size());assertEquals("VERIFIED",call("verify",d,result,null,null,0,"verify-every-hard-control").path("status").asString());
        d=fixtures.mixedDefinition();result=plan(d,20000,"mixed-demand");assertEquals(4,result.path("timetable").path("assignments").size());assertEquals(row(result,"whole1").path("teacherId"),row(result,"whole2").path("teacherId"));
        var policy=(ObjectNode)AudienceReviewCliIT.portion(d,0,0).path("teacherPolicy");policy.put("mode","sharing");policy.putArray("shares").addObject().put("id","share-A").put("teacherId","TE").put("count",1);((ArrayNode)policy.path("shares")).addObject().put("id","share-B").put("teacherId","TH1").put("count",1);result=plan(d,20000,"intentional-sharing");assertEquals(4,result.path("weeklyTeacherAllocations").size());assertEquals("VERIFIED",call("verify",d,result,null,null,0,"verify-sharing").path("status").asString());
    });}
    ObjectNode stabilityDefinition(int sessions,int periods){var d=fixtures.gapDefinition(periods);var p=AudienceReviewCliIT.plan(d,0);p.put("weeklyTotal",sessions);p.putArray("allowedRoomIds").add("ER").add("HR1");var ids=AudienceReviewCliIT.portion(d,0,0).putArray("sessionIds");for(int i=0;i<sessions;i++)ids.add("s"+i);for(JsonNode period:d.path("periods"))((ObjectNode)period).put("adjacentToNext",false);return d;}
    ArrayNode stableAssignments(int... periods){var a=JsonSupport.mapper().createArrayNode();for(int i=0;i<periods.length;i++)a.addObject().put("lessonId","s"+i).put("subjectId","english").put("cohortId","c").put("audienceId","E1").put("allocationId","portion-E1").put("teacherId","TE").put("roomId","ER").put("periodId","p"+periods[i]);return a;}
    @Test void repairPreservesAutomaticTeacherBeforeTimesAndFixedTeacherCannotSubstitute()throws Exception{journey("Repair preserves a comparable automatic weekly teacher despite two forced period moves versus a substitute with zero moves; a genuinely forced automatic replacement is visible once per allocation; fixed teacher unavailability cannot silently substitute",()->{
        var old=stabilityDefinition(2,4);var baseline=review(old,stableAssignments(1,3),"teacher-tier-baseline");var d=old.deepCopy();((ObjectNode)d.path("teachers").get(0)).putArray("availablePeriodIds").add("p2").add("p4");var result=repair(old,baseline,d,20000,"teacher-before-periods");score(result,0,2,0);assertEquals("TE",row(result,"s0").path("teacherId").asString());assertEquals("TE",row(result,"s1").path("teacherId").asString());assertEquals("VERIFIED",call("verify",d,result,null,null,0,"verify-teacher-stable-repair").path("status").asString());
        d=old.deepCopy();((ObjectNode)d.path("teachers").get(0)).putArray("availablePeriodIds");result=repair(old,baseline,d,20000,"forced-automatic-replacement");score(result,1,0,0);assertEquals(1,result.path("changeReport").path("teacherChanges").size());assertEquals(2,result.path("changeReport").path("teacherChanges").get(0).path("sessionIds").size());
        d=old.deepCopy();var policy=(ObjectNode)AudienceReviewCliIT.portion(d,0,0).path("teacherPolicy");policy.put("mode","fixed").put("fixedTeacherId","TE");var fixedBaseline=review(d,stableAssignments(1,3),"fixed-baseline");old=d.deepCopy();((ObjectNode)d.path("teachers").get(0)).putArray("availablePeriodIds");d.put("basedOnRevision",fixedBaseline.path("inputRevision").asString());assertEquals("INVALID_INPUT",call("replan",d,null,old,fixedBaseline,2,"fixed-refuses-substitute","--step-limit","20000").path("status").asString());
    });}
    @Test void repairPeriodAndRoomStabilityPrecedeGaps()throws Exception{journey("One period move retaining gaps beats five moves eliminating them; one room-only move beats two with equal earlier tiers; explicit locked moves count in the same stability tiers and baseline remains exact",()->{
        var old=stabilityDefinition(5,10);var baseline=review(old,stableAssignments(1,3,5,7,9),"period-tier-baseline");var d=old.deepCopy();var available=((ObjectNode)d.path("teachers").get(0)).putArray("availablePeriodIds");for(int i=2;i<=10;i++)available.add("p"+i);AudienceReviewCliIT.plan(d,0).putArray("candidateTeacherIds").add("TE");var result=repair(old,baseline,d,200000,"one-period-before-gap-removal");score(result,0,1,0);assertEquals(28,result.path("score").path("internalGapStudentPeriods").asLong());
        var alternative=review(d,stableAssignments(6,2,3,4,5),"gap-free-five-move-candidate");((ObjectNode)alternative).set("repairContext",AudienceBaseline.context(old,baseline.path("inputRevision").asString(),baseline));alternative=review(d,alternative,"compare-five-move-alternative");score(alternative,0,5,0);assertEquals(0,alternative.path("score").path("internalGapStudentPeriods").asLong());
        old=stabilityDefinition(2,3);baseline=review(old,stableAssignments(1,3),"room-tier-baseline");d=old.deepCopy();((ObjectNode)d.path("rooms").get(0)).putArray("availablePeriodIds").add("p3");var locks=d.putArray("sessionLocks");locks.addObject().put("sessionId","s0").put("periodId","p1");locks.addObject().put("sessionId","s1").put("periodId","p3");result=repair(old,baseline,d,20000,"one-room-before-two");score(result,0,0,1);assertEquals("HR1",row(result,"s0").path("roomId").asString());assertEquals("ER",row(result,"s1").path("roomId").asString());
    });}
    @Test void equalStabilityStudentGapsBeatOrdinaryCoverage()throws Exception{journey("With equal teacher/period/room stability, zero student gaps wins even with worse ordinary coverage; a competing one-move candidate has lower coverage penalty but fourteen student-period gaps",()->{
        var old=stabilityDefinition(2,4);var p=AudienceReviewCliIT.plan(old,0);p.withObject("overrides").put("E2",1);p.putArray("candidateTeacherIds").add("TE").add("TH1");AudienceReviewCliIT.portion(old,0,0).putObject("teacherPolicy").put("mode","fixed").put("fixedTeacherId","TE");var q=p.withArray("portions").addObject().put("id","portion-E2").put("audienceId","E2");q.putArray("sessionIds").add("other");q.putObject("teacherPolicy").put("mode","fixed").put("fixedTeacherId","TH1");q.put("fixedRoomId","HR1");
        var a=stableAssignments(1,4);a.addObject().put("lessonId","other").put("subjectId","english").put("cohortId","c").put("audienceId","E2").put("allocationId","portion-E2").put("teacherId","TH1").put("roomId","HR1").put("periodId","p2");var baseline=review(old,a,"gap-priority-baseline");var d=old.deepCopy();((ObjectNode)d.path("teachers").get(0)).putArray("availablePeriodIds").add("p2").add("p3").add("p4");var result=repair(old,baseline,d,20000,"gap-tier-before-ordinary");score(result,0,1,0);assertEquals(0,result.path("score").path("internalGapStudentPeriods").asLong());assertEquals(42,result.path("quality").path("coverageStudentPeriods").asLong());
        AudienceReviewCliIT.row(a,"s0").put("periodId","p2");var alternate=(ObjectNode)review(d,a,"better-coverage-worse-gap");alternate.set("repairContext",AudienceBaseline.context(old,baseline.path("inputRevision").asString(),baseline));var checked=review(d,alternate,"compare-gap-alternative");score(checked,0,1,0);assertEquals(14,checked.path("score").path("internalGapStudentPeriods").asLong());assertEquals(14,checked.path("quality").path("coverageStudentPeriods").asLong());assertTrue(result.path("score").path("ordinaryPreferencePenalty").asLong()>checked.path("score").path("ordinaryPreferencePenalty").asLong());
    });}
    @Test void boundedFailureAndExhaustiveFailureNeverPublishPartialTimetables()throws Exception{journey("A one-step budget reports no candidate without claiming infeasibility; exhaustive resource contradiction reports the supported finite-search conclusion; neither publishes a partial timetable or mutates inputs",()->{
        var d=fixtures.definition();var r=call("plan",d,null,null,null,3,"one-step-no-candidate","--step-limit","1");assertEquals("NO_FEASIBLE_SOLUTION_FOUND",r.path("status").asString());assertEquals("STEP_LIMIT",r.path("terminationReason").asString());assertFalse(r.path("searchOutcome").path("searchExhausted").asBoolean());assertFalse(r.has("timetable"));
        d=fixtures.gapDefinition(1);var p=AudienceReviewCliIT.plan(d,0);p.put("weeklyTotal",1).putArray("candidateTeacherIds").add("TE");AudienceReviewCliIT.portion(d,0,0).putArray("sessionIds").add("a");p.withObject("overrides").put("E2",1);p.putArray("allowedRoomIds").add("ER");var q=p.withArray("portions").addObject().put("id","portion-E2").put("audienceId","E2");q.putArray("sessionIds").add("b");q.putObject("teacherPolicy").put("mode","automatic");r=call("plan",d,null,null,null,3,"exhaustive-shared-resource-contradiction","--step-limit","1000");assertTrue(r.path("searchOutcome").path("searchExhausted").asBoolean());assertEquals("SEARCH_EXHAUSTED",r.path("terminationReason").asString());assertTrue(r.path("searchDiagnostics").path("constraints").toString().contains("hard.teacher-period"));assertFalse(r.has("timetable"));
    });}
    @Test void crossingMembershipAndThreeGroupsGenerateWithoutApproximation()throws Exception{journey("Crossing 7/7/7/7 memberships generate same-split parallel teaching without cross-split overlap; missing memberships refuse. Three actual groups 10/9/9 receive distinct teachers/rooms without changing counts",()->{
        var d=fixtures.definition();var c=(ObjectNode)d.path("cohorts").get(0);var h=(ObjectNode)c.path("splits").get(1);h.put("groupCount",2);var groups=(ArrayNode)h.path("groups");groups.remove(3);groups.remove(2);for(JsonNode g:groups)((ObjectNode)g).put("size",14);var portions=(ArrayNode)AudienceReviewCliIT.plan(d,1).path("portions");portions.remove(3);portions.remove(2);for(JsonNode room:d.path("rooms"))((ObjectNode)room).put("capacity",14);
        var relationship=c.putObject("relationships").put("mode","joint");relationship.putObject("unions");relationship.putArray("splitIds").add("E").add("H");var rows=relationship.putArray("intersections");for(String e:List.of("E1","E2"))for(String g:List.of("H1","H2"))rows.addObject().put("count",7).putArray("groupIds").add(e).add(g);
        var p=AudienceReviewCliIT.plan(d,0);p.putArray("candidateTeacherIds").add("TE").add("TH2");p.putArray("allowedRoomIds").add("ER").add("HR2");var teacher=(ObjectNode)d.path("teachers").get(2);teacher.putArray("qualifiedSubjectIds").add("english").add("handicraft");((ObjectNode)teacher.path("eligibleClassIdsBySubject")).putArray("english").add("c");var result=plan(d,10000,"crossing-generated");assertEquals(row(result,"e1").path("periodId"),row(result,"e2").path("periodId"));assertNotEquals(row(result,"e1").path("periodId"),row(result,"h1").path("periodId"));assertEquals("VERIFIED",call("verify",d,result,null,null,0,"verify-crossing-generated").path("status").asString());c.remove("relationships");assertEquals("INVALID_INPUT",call("plan",d,null,null,null,2,"missing-crossing-refuses","--step-limit","10000").path("status").asString());
        d=fixtures.mixedDefinition();c=(ObjectNode)d.path("cohorts").get(0);var split=(ObjectNode)c.path("splits").get(0);split.put("groupCount",3);groups=split.putArray("groups");for(int i=1;i<=3;i++)groups.addObject().put("id","G"+i).put("displayName","Group "+i).put("size",i==1?10:9);p=AudienceReviewCliIT.plan(d,0);p.put("delivery","grouped").put("wholeClassCount",0).put("weeklyTotal",1);p.putObject("overrides");var qs=p.putArray("portions");
        for(int i=1;i<=3;i++){var q=qs.addObject().put("id","portion-G"+i).put("audienceId","G"+i);q.putArray("sessionIds").add("g"+i);q.putObject("teacherPolicy").put("mode","automatic");((ObjectNode)d.path("rooms").get(i-1)).put("capacity",i==1?10:9);}AudienceReviewCliIT.grid(d,1);result=plan(d,10000,"three-group-generated");assertEquals(3,result.path("timetable").path("assignments").size());var teachers=new HashSet<String>();var rooms=new HashSet<String>();for(JsonNode a:result.path("timetable").path("assignments")){teachers.add(a.path("teacherId").asString());rooms.add(a.path("roomId").asString());}assertEquals(3,teachers.size());assertEquals(3,rooms.size());assertEquals("VERIFIED",call("verify",d,result,null,null,0,"verify-three-group-generated").path("status").asString());
    });}
    @Test void unequalBlocksCoverageAndLocksGenerateWholeDurations()throws Exception{journey("A selected required double starts with a single and another selected subject fills its second period; exact coverage, teacher continuity, fixed session lock and complete duration are retained by generation and independent review",()->{
        var d=fixtures.gapDefinition(2);AudienceReviewCliIT.plan(d,0).putArray("blockRules").addObject().put("id","double").put("length",2).put("count",1).put("operator","EXACTLY");
        for(int i=0;i<2;i++){
            String subject=i==0?"handicraft":"music",id=i==0?"h":"m",teacher=i==0?"TH1":"TH2";if(i==1)d.withArray("subjects").addObject().put("id",subject).put("displayName","Music");var t=(ObjectNode)d.path("teachers").get(i+1);t.putArray("qualifiedSubjectIds").add("english").add(subject);((ObjectNode)t.path("eligibleClassIdsBySubject")).putArray(subject).add("c");var p=d.withArray("audiencePlans").addObject().put("id",id+"-plan").put("classId","c").put("subjectId",subject).put("delivery","grouped").put("splitId","E").put("weeklyTotal",1).put("wholeClassCount",0);p.putObject("overrides").put("E1",0);p.putArray("candidateTeacherIds").add(teacher);p.putArray("allowedRoomIds").add("HR1").add("HR2");var q=p.putArray("portions").addObject().put("id",id+"-portion").put("audienceId","E2");q.putArray("sessionIds").add(id);q.putObject("teacherPolicy").put("mode","automatic");
        }
        var start=AudienceReviewCliIT.rule(d,"unequal","START_TOGETHER",1,"portion-E1","h-portion");((ObjectNode)start.path("activities").get(0)).put("unit","BLOCK").put("blockRuleId","double");var coverage=AudienceReviewCliIT.rule(d,"duration","COVERAGE",1,"portion-E1","h-portion","m-portion");((ObjectNode)coverage.path("activities").get(0)).put("unit","BLOCK").put("blockRuleId","double");d.putArray("sessionLocks").addObject().put("sessionId","a").put("periodId","p1").put("roomId","ER");var result=plan(d,10000,"unequal-complete-duration");assertEquals("p1",row(result,"a").path("periodId").asString());assertEquals("p2",row(result,"b").path("periodId").asString());assertEquals("p1",row(result,"h").path("periodId").asString());assertEquals("p2",row(result,"m").path("periodId").asString());assertEquals(0,result.path("quality").path("coverageStudentPeriods").asLong());assertEquals("VERIFIED",call("verify",d,result,null,null,0,"verify-unequal-generated").path("status").asString());
    });}
    @Test void timeBudgetAndProcessCancellationPreserveSourcePair()throws Exception{journey("A time-bounded large search reports its actual limit and never claims global optimality; terminating a running published process leaves source/accepted pair and an existing output artifact unchanged, with no late publication",()->{
        var d=stabilityDefinition(10,20);var r=call("plan",d,null,null,null,0,"time-budget-valid-candidate","--time-limit","2s","--seed","0");assertEquals("TIME_LIMIT",r.path("terminationReason").asString());assertFalse(r.path("searchOutcome").path("globalOptimalityClaimed").asBoolean());assertEquals("VERIFIED",call("verify",d,r,null,null,0,"verify-time-limited-candidate").path("status").asString());
        var dir=OUTPUT.resolve("cancelled-"+SEQUENCE.incrementAndGet());Files.createDirectories(dir);var source=dir.resolve("definition.json");var accepted=dir.resolve("accepted.json");var output=dir.resolve("output.json");byte[] input=JsonSupport.mapper().writeValueAsBytes(d),baseline=JsonSupport.mapper().writeValueAsBytes(r),prior="Previous output artifact".getBytes(java.nio.charset.StandardCharsets.UTF_8);Files.write(source,input);Files.write(accepted,baseline);Files.write(output,prior);var jar=temporary.resolve("cancel.jar");Files.copy(Path.of("target/school-kernel.jar"),jar);
        var process=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-jar",jar.toString(),"plan","--definition",source.toAbsolutePath().toString(),"--time-limit","20s","--force","--output",output.toAbsolutePath().toString()).redirectErrorStream(true).redirectOutput(dir.resolve("process.log").toFile()).start();try{Thread.sleep(1800);assertTrue(process.isAlive());process.destroy();assertTrue(process.waitFor(5,TimeUnit.SECONDS));assertArrayEquals(input,Files.readAllBytes(source));assertArrayEquals(baseline,Files.readAllBytes(accepted));assertArrayEquals(prior,Files.readAllBytes(output));}finally{if(process.isAlive()){process.destroyForcibly();process.waitFor();}}
    });}
}
